/**
 * Get the path to an icon by category and name
 * @param category - The icon category (e.g., 'demographics-group', 'device-cellphone')
 * @param iconName - The icon name (e.g., 'adult', 'default')
 * @returns The relative path to the icon
 *
 * @example
 * getIconPath('demographics-group', 'adult')
 * // returns 'icons/demographics-group/adult.svg'
 */
export function getIconPath(
    category: keyof typeof icons,
    iconName: keyof (typeof icons)[typeof category]
): string {
    const categoryIcons = icons[category] as Record<string, string>;
    return categoryIcons[iconName] || '';
}

/**
 * Get all available icon categories
 * @returns Array of category names
 */
export function getCategories(): (keyof typeof icons)[] {
    return Object.keys(icons) as (keyof typeof icons)[];
}

/**
 * Get all icons in a category
 * @param category - The icon category
 * @returns Object with icon names as keys and paths as values
 */
export function getCategoryIcons(category: keyof typeof icons) {
    return icons[category] || {};
}
